import{_ as t,o as a,c as d,a2 as i}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"InlineEdit","description":"","frontmatter":{},"headers":[],"relativePath":"components/inline-edit.md","filePath":"components/inline-edit.md"}'),n={name:"components/inline-edit.md"};function o(r,e,l,s,h,c){return a(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="inlineedit" tabindex="-1">InlineEdit <a class="header-anchor" href="#inlineedit" aria-label="Permalink to &quot;InlineEdit&quot;">​</a></h1><p>InlineEdit is text that is changed where it stands.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a name or a description shown in a panel or a header, where a field would be too heavy. Empty and editable, it shows the action &quot;+ placeholder&quot;; with a value, the text and a pencil; not editable, the text alone (nothing when empty). Enter commits and Escape restores; <code>multiline</code> adds lines with Enter and commits on blur or ⌘/Ctrl+Enter. When the text is emptied, the application decides what takes its place. A name entered in a form is a <a href="./text-input">TextInput</a> in a <a href="./field">Field</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>&#39;&#39;</code></td><td>The text (bindable)</td></tr><tr><td><code>placeholder</code></td><td>required</td><td>The action shown when empty</td></tr><tr><td><code>onCommit</code></td><td>required</td><td>Called with the changed text, trimmed</td></tr><tr><td><code>editable</code></td><td><code>true</code></td><td><code>false</code> shows the text only</td></tr><tr><td><code>title</code></td><td><code>false</code></td><td>The size and weight of h2</td></tr><tr><td><code>multiline</code></td><td><code>false</code></td><td>Several lines</td></tr><tr><td><code>label</code></td><td></td><td>The accessible name (the placeholder by default)</td></tr><tr><td><code>editing</code></td><td><code>false</code></td><td>Being edited (bindable); <code>true</code> starts an edit</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Read, it is a control without a line, of the height its container declares and without padding at the sides, so its edge lines up with the text around it; hover shows the raise surface and turns the faint pencil muted. Edited, it is a control with a blue-ink line and pad-sm at the sides. The text of one line is trimmed to its ink and ends with an ellipsis; several lines wrap, and the first line sits where a one-line control puts its text. The empty action is blue-ink, underlined on hover. Escape does not reach a panel or a modal around it.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/inline-edit/" title="InlineEdit" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/inline-edit/" target="_blank" rel="noopener">InlineEdit</a></figcaption></figure>',10)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
